    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (2,1,'traffic-rules','multiple_choice','What is the speed limit on Nigerian highways?','["80 km/h","100 km/h","120 km/h","140 km/h"]',1,'Highways: 100 km/h. Expressways: 120 km/h. Urban: 50 km/h.',1,true),
    (2,1,'traffic-rules','multiple_choice','What is the speed limit in residential areas in Nigeria?','["20 km/h","30 km/h","40 km/h","50 km/h"]',1,'Residential areas: 30 km/h. Children may be playing.',1,true),
    (2,1,'traffic-rules','multiple_choice','Exceeding the speed limit by more than 20 km/h can result in:','["Warning only","Fine of N3,000 and 3 penalty points","License suspension","No penalty"]',1,'FRSC rule: exceeding by 20+ km/h = N3,000 fine and 3 penalty points.',2,true),
    (2,1,'traffic-rules','multiple_choice','What is the speed limit near a construction zone?','["Normal speed","50 km/h or as posted","30 km/h always","80 km/h"]',1,'Follow posted speed limit at construction zones, typically 50 km/h or lower.',2,true),
    (2,1,'traffic-rules','multiple_choice','When driving in heavy rain, you should:','["Maintain speed limit","Reduce speed by at least 30%","Stop completely","Speed up to get home faster"]',1,'Reduce speed by at least 30% in heavy rain. Stopping distance increases significantly.',1,true),
    (2,1,'traffic-rules','multiple_choice','What is the minimum driving age in Nigeria?','["16","17","18","21"]',2,'The minimum driving age in Nigeria is 18 years.',1,true),
    (2,1,'traffic-rules','multiple_choice','What is the legal blood alcohol concentration limit in Nigeria?','["0.08%","0.05%","0.02%","0.00%"]',3,'Nigeria has a zero tolerance policy. Any detectable alcohol is an offence.',2,true),
    (2,1,'traffic-rules','multiple_choice','Using a mobile phone while driving is:','["Allowed with hands-free","Allowed if stopped","Prohibited","Allowed if slow"]',2,'Using a mobile phone while driving is prohibited. Use hands-free if necessary.',1,true),
    (2,1,'traffic-rules','multiple_choice','Seat belts are required for:','["Driver only","Front seat only","All occupants","Adults only"]',2,'All occupants must wear seat belts in Nigeria.',1,true),
    (2,1,'traffic-rules','multiple_choice','What is the fine for not wearing a seatbelt?','["N1,000","N2,000","N3,000","N5,000"]',1,'FRSC imposes a N2,000 fine for not wearing a seatbelt.',2,true),
    (2,1,'traffic-rules','multiple_choice','When approaching a speed bump without signage, you should:','["Speed up","Slow down and proceed carefully","Stop completely","Honk"]',1,'Slow down and proceed carefully over unmarked speed bumps.',1,true),
    (2,1,'traffic-rules','multiple_choice','What is the maximum speed limit for motorcycles in urban areas?','["30 km/h","40 km/h","50 km/h","60 km/h"]',2,'Motorcycles follow the same speed limits as cars: 50 km/h in urban areas.',2,true),
    (2,1,'traffic-rules','multiple_choice','Driving without a valid licence is punishable by:','["Warning","Fine and/or imprisonment","Vehicle impoundment only","No penalty"]',1,'Driving without a valid licence can result in a fine and/or imprisonment.',2,true),
    (2,1,'traffic-rules','multiple_choice','What document must you carry while driving?','["Vehicle manual","Driver licence and vehicle papers","Insurance only","Registration only"]',1,'Always carry your driver licence, vehicle registration, and proof of insurance.',1,true),
    (2,1,'traffic-rules','multiple_choice','Vehicle inspection is required:','["Never","Annually","Every 2 years","Every 5 years"]',1,'Vehicle inspection is required annually in Nigeria.',2,true),
    (2,2,'traffic-rules','multiple_choice','At an uncontrolled T-junction, who has right of way?','["The vehicle on the minor road","The vehicle on the major road","The faster vehicle","The larger vehicle"]',1,'Traffic on the major road has right of way at a T-junction.',1,true),
    (2,2,'traffic-rules','multiple_choice','At a crossroads without signs or lights, you should give way to:','["Traffic from the left","Traffic from the right","Traffic from the front","The faster vehicle"]',1,'Give way to traffic from the right at uncontrolled crossroads.',1,true),
    (2,2,'traffic-rules','multiple_choice','When two vehicles arrive at a junction simultaneously, who proceeds first?','["The larger vehicle","The vehicle on the right","The faster vehicle","The vehicle going straight"]',1,'The vehicle on the right has right of way when arriving simultaneously.',2,true),
    (2,2,'traffic-rules','multiple_choice','When turning right at a junction, you should:','["Turn without signaling","Signal, check mirrors, check blind spot, then turn","Honk and turn","Wait for all traffic to clear"]',1,'Signal, check mirrors and blind spot, then turn when safe.',1,true),
    (2,2,'traffic-rules','multiple_choice','When a police officer directs traffic at a junction, you should:','["Follow traffic lights","Follow the officer signals","Follow road signs","Use your judgement"]',1,'A police officer signals override traffic lights and signs. Always follow the officer.',1,true),
    (2,2,'traffic-rules','multiple_choice','At a roundabout with multiple lanes, to take the third exit you should:','["Use left lane","Use right lane","Use middle lane","Use any lane"]',2,'Use the right lane for the third exit (in left-hand traffic). Signal right after passing the second exit.',2,true),
    (2,2,'traffic-rules','multiple_choice','When approaching a roundabout, you must:','["Speed up","Give way to traffic already in the roundabout","Stop completely","Honk"]',1,'Give way to traffic already circulating in the roundabout.',1,true),
    (2,2,'traffic-rules','multiple_choice','When an ambulance approaches from behind with sirens, you should:','["Speed up","Pull over to the left and stop if safe","Stop in your lane","Ignore it"]',1,'Pull over to the left and stop if safe. Allow emergency vehicles to pass.',1,true),
    (2,2,'traffic-rules','multiple_choice','At a zebra crossing with pedestrians waiting, you should:','["Drive around them","Stop and let them cross","Honk for them to move","Speed up"]',1,'Pedestrians have right of way at zebra crossings. Stop and let them cross.',1,true),
    (2,2,'traffic-rules','multiple_choice','When a funeral procession is passing, you should:','["Drive through it","Stop and wait","Honk to pass","Use another route"]',1,'Stop and wait for a funeral procession to pass. It is respectful and required.',2,true),
    (2,2,'traffic-rules','multiple_choice','A flashing amber beacon at a crossing means:','["Go","Slow down and prepare to stop","Stop completely","No action needed"]',1,'Slow down and prepare to stop. Pedestrians may be crossing.',2,true),
    (2,2,'traffic-rules','multiple_choice','When turning left at a junction, you must give way to:','["Traffic from behind","Oncoming traffic","Traffic from the right only","Pedestrians only"]',1,'When turning left, give way to oncoming traffic and pedestrians crossing.',2,true),
    (2,2,'traffic-rules','multiple_choice','A green filter arrow at traffic lights means:','["Stop","Proceed in that direction only","Yield to all","Wait for full green"]',1,'A green filter arrow means you may proceed in that direction.',2,true),
    (2,2,'traffic-rules','multiple_choice','When traffic lights are not working, you should:','["Proceed at speed","Treat as a give way junction","Stop completely","Revers"]',1,'Treat as a give way junction. Give way to traffic from the right.',2,true),
    (2,2,'traffic-rules','multiple_choice','At a box junction, you should not enter unless:','["Your exit is clear","The light is green","The way is partially clear","You are turning right"]',0,'Do not enter a box junction unless your exit is clear.',2,true),
    (2,3,'traffic-rules','multiple_choice','On a three-lane road, the right lane is for:','["Normal driving","Overtaking and faster traffic","Heavy vehicles only","Parking"]',1,'Right lane is for overtaking and faster traffic. Keep left unless overtaking.',1,true),
    (2,3,'traffic-rules','multiple_choice','Before overtaking, you should:','["Just accelerate","Check mirrors, blind spot, signal, ensure clear view","Honk and go","Follow closely"]',1,'Check mirrors, blind spot, signal, and ensure a clear view before overtaking.',1,true),
    (2,3,'traffic-rules','multiple_choice','After overtaking, you should return to the left lane:','["Immediately","When you can see the overtaken vehicle in your mirror","After 500m","When the other driver honks"]',1,'Return to the left lane when you can see the overtaken vehicle in your mirror.',1,true),
    (2,3,'traffic-rules','multiple_choice','You must not overtake:','["On a straight road","On a bend, at a junction, or near a crossing","In good weather","On a wide road"]',1,'Never overtake on bends, at junctions, near crossings, or when visibility is poor.',1,true),
    (2,3,'traffic-rules','multiple_choice','Tailgating (following too closely) is:','["Safe driving","Dangerous and prohibited","Recommended in traffic","Only for experienced drivers"]',1,'Tailgating is dangerous and prohibited. Maintain safe following distance.',1,true),
    (2,3,'traffic-rules','multiple_choice','The two-second rule means:','["Wait 2 seconds before moving","Keep at least 2 seconds of following distance","Honk every 2 seconds","Check mirrors every 2 seconds"]',1,'Keep at least 2 seconds of following distance behind the vehicle in front.',1,true),
    (2,3,'traffic-rules','multiple_choice','In wet conditions, the following distance should be:','["Same as dry","At least 4 seconds","1 second","10 seconds"]',1,'Double the following distance to at least 4 seconds in wet conditions.',2,true),
    (2,3,'traffic-rules','multiple_choice','When being overtaken, you should:','["Speed up","Maintain your speed and position","Slow down","Move right"]',1,'Maintain your speed and position when being overtaken. Do not accelerate.',2,true),
    (2,3,'traffic-rules','multiple_choice','Overtaking on the left is permitted when:','["Never","The vehicle ahead is signaling to turn right","In heavy traffic","On highways"]',1,'You may overtake on the left only when the vehicle ahead is signaling to turn right.',2,true),
    (2,3,'traffic-rules','multiple_choice','When changing lanes, you should:','["Just move","Signal, check mirrors, check blind spot, then move","Honk and move","Move quickly"]',1,'Signal, check mirrors and blind spot, then move when safe.',1,true),
    (2,3,'traffic-rules','multiple_choice','A solid white line between lanes means:','["You may cross it","You must not cross it","You may cross to overtake","It is a suggestion"]',1,'A solid white line means you must not cross it. Stay in your lane.',1,true),
    (2,3,'traffic-rules','multiple_choice','A broken white line between lanes means:','["No crossing","You may cross if safe","You must cross","It is a hazard"]',1,'A broken white line means you may cross if it is safe to do so.',1,true),
    (2,3,'traffic-rules','multiple_choice','A double solid white line means:','["Cross if safe","Never cross","Cross only to overtake","Cross only to turn"]',1,'Double solid white lines: never cross. They indicate maximum restriction.',2,true),
    (2,3,'traffic-rules','multiple_choice','A yellow line on the edge of the road means:','["Parking allowed","No stopping or parking","Speed limit","Bus lane"]',1,'A yellow line on the road edge means no stopping or parking.',2,true),
    (2,3,'traffic-rules','multiple_choice','A box with a cross in a junction means:','["Do not block the junction","Crossroads ahead","No turning","Accident zone"]',0,'A yellow box with diagonal lines means do not enter unless your exit is clear.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A valid Nigerian driver licence must be:','["Carried at all times when driving","Kept at home","Shown only to FRSC","Renewed every 10 years"]',0,'Always carry your valid driver licence when driving.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Vehicle registration must be renewed:','["Never","Annually","Every 2 years","Every 5 years"]',1,'Vehicle registration must be renewed annually in Nigeria.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Third-party insurance is:','["Optional","Mandatory for all vehicles","Only for commercial vehicles","Only for new vehicles"]',1,'Third-party insurance is mandatory for all vehicles in Nigeria.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Driving with expired registration is:','["Allowed for 30 days","An offence punishable by fine","Only a warning","Allowed if insured"]',1,'Driving with expired registration is an offence. Fine and possible impoundment.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A learner driver must be accompanied by:','["Anyone","A licensed driver with at least 3 years experience","A family member","Another learner"]',1,'A learner must be accompanied by a licensed driver with at least 3 years of experience.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Learner plates must be displayed:','["Front only","Front and back of the vehicle","Back only","On the roof"]',1,'Learner plates (L plates) must be displayed on both front and back.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Reversing on a highway is:','["Allowed if slow","Strictly prohibited","Allowed if no traffic","Allowed at night"]',1,'Reversing on a highway is strictly prohibited. It is extremely dangerous.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Making a U-turn on a highway is:','["Allowed if no traffic","Prohibited except at designated points","Allowed at night","Allowed if slow"]',1,'U-turns on highways are prohibited except at designated points.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Parking on a pedestrian crossing is:','["Allowed for 5 minutes","Prohibited","Allowed if no pedestrians","Allowed at night"]',1,'Parking on a pedestrian crossing is prohibited. It blocks visibility.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Parking within 15 metres of a junction is:','["Allowed","Prohibited","Allowed if no traffic","Allowed at night"]',1,'Parking within 15 metres of a junction is prohibited. It blocks visibility.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Parking on the wrong side of the road is:','["Allowed","An offence","Allowed if no traffic","Only a warning"]',1,'Parking on the wrong side of the road is an offence. Always park on the left.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Using hazard lights while moving is:','["Always allowed","Only in an emergency or to warn of a hazard","Never allowed","Allowed in traffic"]',1,'Hazard lights while moving are only for emergencies or to warn of a sudden hazard ahead.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Driving against the flow of traffic (one-way) is:','["Allowed if slow","A serious offence","Allowed if no traffic","Only a warning"]',1,'Driving against traffic on a one-way street is a serious offence. Very dangerous.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Overloading a vehicle with passengers is:','["Allowed if comfortable","An offence","Allowed for short trips","Only a warning"]',1,'Overloading is an offence. It affects vehicle handling and braking.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Children under 12 should:','["Sit in front","Sit in the back with seatbelt","Stand if no seats","Sit on an adult lap"]',1,'Children under 12 should sit in the back with proper seatbelts.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Riding a motorcycle without a helmet is:','["Allowed in town","Prohibited","Allowed if slow","Only a warning"]',1,'Helmets are mandatory for all motorcycle riders and passengers in Nigeria.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','A motorcycle carrying more than one passenger is:','["Always allowed","An offence unless designed for it","Allowed in town","Allowed if slow"]',1,'Motorcycles may only carry the number of passengers they are designed for.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Driving at night without headlights is:','["Allowed in lit areas","Prohibited","Allowed if slow","Only a warning"]',1,'Headlights are required at night and in poor visibility. It is an offence not to use them.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Using high beam in built-up areas is:','["Required","Prohibited — use dipped beam","Allowed","Only for trucks"]',1,'Use dipped beam in built-up areas. High beam dazzles other drivers.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Failing to stop at a stop sign is:','["A minor issue","A serious offence","Only a warning","Allowed if no traffic"]',1,'Failing to stop at a stop sign is a serious offence. You must come to a complete stop.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Running a red light is:','["A minor offence","A serious offence with heavy penalty","Allowed if no traffic","Only a warning"]',1,'Running a red light is a serious offence. Heavy fine and penalty points.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','The FRSC is responsible for:','["Vehicle sales","Road safety enforcement","Driver training only","Insurance"]',1,'FRSC (Federal Road Safety Corps) is responsible for road safety enforcement in Nigeria.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','The VIO is responsible for:','["Road safety","Vehicle inspection and roadworthiness","Driver licensing","Insurance"]',1,'VIO (Vehicle Inspection Office) handles vehicle inspection and roadworthiness.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','LASTMA operates in which state?','["Lagos","Abuja","Rivers","Kano"]',0,'LASTMA (Lagos State Traffic Management Authority) operates in Lagos State.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Penalty points on your licence can lead to:','["Nothing","Licence suspension","Lower insurance","Better driving"]',1,'Accumulating penalty points can lead to licence suspension.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','How many penalty points lead to suspension in Nigeria?','["10","12","15","20"]',1,'Accumulating 12 penalty points within a period can lead to licence suspension.',3,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a cracked windscreen is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if small crack"]',1,'A cracked windscreen that impairs vision makes the vehicle not roadworthy.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','Driving with worn tyres is:','["Safe","An offence — minimum 1.6mm tread depth required","Only a warning","Allowed if slow"]',1,'Worn tyres are an offence. Minimum tread depth is 1.6mm.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without functioning brake lights is:','["Roadworthy","Not roadworthy","Only a warning","Allowed in daylight"]',1,'Non-functioning brake lights make the vehicle not roadworthy.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without a horn is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if quiet"]',1,'A functioning horn is required. Vehicle is not roadworthy without one.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without rearview mirrors is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if experienced"]',1,'Rearview mirrors are required. Vehicle is not roadworthy without them.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without functioning wipers is:','["Roadworthy","Not roadworthy","Only a warning","Allowed in dry season"]',1,'Functioning wipers are required. Vehicle is not roadworthy without them.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with excessive exhaust smoke is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if old vehicle"]',1,'Excessive exhaust smoke means the vehicle is not roadworthy.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without a speedometer is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if experienced"]',1,'A functioning speedometer is required for roadworthiness.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a spare tyre that is flat is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if near home"]',1,'A flat spare tyre means the vehicle is not fully roadworthy.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A commercial vehicle without a fire extinguisher is:','["Roadworthy","Not roadworthy","Only a warning","Allowed if small vehicle"]',1,'Commercial vehicles must carry a fire extinguisher.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without a first aid kit is:','["Roadworthy","Not roadworthy but only a warning","Required for commercial only","Recommended for all"]',3,'A first aid kit is recommended for all vehicles, required for commercial.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with tinted windows without permit is:','["Roadworthy","An offence","Only a warning","Allowed if light tint"]',1,'Tinted windows without a police permit are an offence in Nigeria.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a fake number plate is:','["Roadworthy","A serious offence","Only a warning","Allowed if pending"]',1,'Fake number plates are a serious offence. Vehicle will be impounded.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle without a number plate is:','["Roadworthy","An offence","Only a warning","Allowed if new"]',1,'Driving without a number plate is an offence.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with an expired number plate is:','["Roadworthy","An offence","Only a warning","Allowed for 30 days"]',1,'An expired number plate is an offence. Renew promptly.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a personalised number plate without approval is:','["Roadworthy","An offence","Only a warning","Allowed if registered"]',1,'Personalised number plates require FRSC approval. Using without is an offence.',3,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a diplomatic plate has:','["No special rights","Immunity from traffic laws","Reduced fines","Faster processing"]',0,'Diplomatic plates do not grant immunity from traffic laws. All rules apply.',3,true),
    (2,NULL,'traffic-rules','multiple_choice','A vehicle with a government plate:','["Has no special rights on the road","Has right of way always","Can ignore traffic lights","Can park anywhere"]',0,'Government plates do not grant special road rights. Follow all traffic rules.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','When stopped by FRSC, you should:','["Speed away","Stop, wind down window, present documents","Argue","Ignore them"]',1,'Stop safely, wind down your window, and present your documents when asked.',1,true),
    (2,NULL,'traffic-rules','multiple_choice','Bribing a traffic officer is:','["A minor offence","A serious criminal offence","A common practice","A traffic violation"]',1,'Bribing a traffic officer is a serious criminal offence in Nigeria.',2,true),
    (2,NULL,'traffic-rules','multiple_choice','A traffic ticket should be:','["Torn up","Paid or contested in court","Ignored","Given to someone else"]',1,'A traffic ticket should be paid within the specified period or contested in court.',2,true);
